from collections import defaultdict

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        NEG_INF = -10**30

        positions = defaultdict(list)
        for i, v in enumerate(nums):
            if v < 0:
                positions[v].append(i)

        size = 1
        while size < n:
            size <<= 1

        total = [0] * (2 * size)
        pref = [NEG_INF] * (2 * size)
        suff = [NEG_INF] * (2 * size)
        best = [NEG_INF] * (2 * size)

        def pull(i: int) -> None:
            l, r = i * 2, i * 2 + 1
            total[i] = total[l] + total[r]
            pref[i] = max(pref[l], total[l] + pref[r])
            suff[i] = max(suff[r], total[r] + suff[l])
            best[i] = max(best[l], best[r], suff[l] + pref[r])

        for i, v in enumerate(nums):
            p = size + i
            total[p] = pref[p] = suff[p] = best[p] = v

        for i in range(size - 1, 0, -1):
            pull(i)

        def update(idx: int, value: int, active: bool) -> None:
            p = size + idx
            if active:
                total[p] = pref[p] = suff[p] = best[p] = value
            else:
                total[p] = 0
                pref[p] = suff[p] = best[p] = NEG_INF

            p >>= 1
            while p:
                pull(p)
                p >>= 1

        ans = best[1]

        # Removing a non-negative value can never improve over the original array:
        # the corresponding original subarray would have at least the same sum.
        for x, inds in positions.items():
            if len(inds) == n:
                continue

            for i in inds:
                update(i, 0, False)

            ans = max(ans, best[1])

            for i in inds:
                update(i, x, True)

        return ans
